| occasion              = {{nowrap|Twelfth Sunday after [[Trinity Sunday|Trinity]]}}
| performed             = {{Timeline-event|date={{Start date|1725|08|19|df=y}}|location=[[Leipzig]]}}
| movements             = five
| chorale               = {{based on|"{{langr|de|[[Lobe den Herren, den mächtigen König der Ehren]]}}|[[Joachim Neander]]}}
| vocal                 = [[SATB|{{abbr|SATB|soprano, alto, tenor and bass}}]] choir and solo
