tf = \tempo 4 = 39
trumpet = \relative c''' { \global \set midiInstrument = "trumpet"
  \repeat volta 2 { <g e c>4^"3 trumpets" <g c, e,> <g d g,> | <g e c>4. q8 <a fis c>4 |
    <b g d> <g d g,> <b g d> | <c g e> <b g f> << { <c e,>8 <a c,> } \\ { g4 } >> |
    <b g d>2 <c g e>4 | }
  <g e>4. << { bes8 a [g] } \\ { g16 f e8 f16 e } >> | <f d>2. |
  << { c4. d8 d4 | e8 [d] e [f] <g e> <a f> } \\ { e,4 r4 r | <c' g>4. <d g,>8 c4 } >> | <b' g d>2. |
  << { g2.~ | g8 [f] g [a] g a | g a16 b b4 c } \\
     { <d, g,>4 q2 | <c g>4 <f d> <e c>8 <c e,> | <d g,>2 <e g,>4 } >> \bar "|."
}

soprano = \new Voice = "soprano" \relative c'' {
  \global \voiceOne \clef treble \set midiInstrument = "violin" %"oboe"
  \repeat volta 2 { \tn c4 c g' | e4. d8 c4 | b4. a8 g4 | c d e8 (f) | d2 \tf c4\fermata | }
  \tn e4. d8 e4 | f2.\fermata e4. f8 g4 | g4. f8 e4 | d2.\fermata |
  g,4 a b | c d e8. (f16) | d2 \tf c4\fermata \bar "|."
}

alto = \new Voice \relative c'' { \global \voiceTwo \set midiInstrument = "viola" %"flute"
  \repeat volta 2 { g4\ff g g | g4. g8 fis4 | d g g | g b g | g (f) e | }
  g4. g8 cis,4 | a'2. | a4. a8 d,4 | c g' g | g2. |
  d4 d d | g g g | g2 e4 \bar "|."
}

tenor = \new Voice \relative c' { \global \voiceThree \clef bass \set midiInstrument = "cello" %"clarinet"
  \repeat volta 2 { e4 e d | c4. g8 c4 | g' g, d' | c f, c' | d b g | }
  e'4. e8 e ([cis]) | d2. | e4. c8 b ([a]) | g4 b c | b2. |
  b4 d g, | g g g8 (c) | c4 (b) g \bar "|."
}

bass = \relative c { \global \voiceFour \set midiInstrument = "contrabass" %"bassoon"
  \repeat volta 2 { c4 c' b | c4. b8 a4 | g g, f' | e d c | g' g, c | }
  c4 e a | d,2. | a'4 g f | e4. d8 c4 | g2. |
  g'4 f8 ([e]) f (d) | e4 b c | g' g, c \bar "|."
}

verse = \new Lyrics = "firstVerse" \lyricsto "soprano" {
  << { \set stanza = "5." Lo -- be den Her -- ren, was in mir ist, lo -- be den Na -- men. }
  \new Lyrics = "secondVerse" \with { alignBelowContext = "firstVerse" } { \set associatedVoice = "soprano"
    Al -- les, was O -- dem hat, lo -- be mit A -- bra -- hams Sa -- men. } >>
  Er ist dein Licht,
  See -- le, ver -- giss es ja nicht;
  Lo -- ben -- de, schlie -- ße mit A -- men!
}

timpani = \relative c { \global \set midiInstrument = "timpani"
  \repeat volta 2 { c4^"timpani" c g | c4. c8 c4 | g g g | c g c | g8 g16 g g8 g c4 | }
  R2. | R | c4 r4 r4 | c4. g8 c4 | g2. | g4 g2 | c4 g c | g2 c4 \bar "|."
}

\score {
  <<
    \new Staff \with { \magnifyStaff #3/4 } \trumpet
    \new ChoirStaff
    <<
      \new Staff
      <<
        { \soprano }
        { \alto }
        \context Lyrics = "soprano" { \lyricsto "soprano" { \verse } }
      >>

      \new Staff
         \with { \override VerticalAxisGroup.staff-staff-spacing = % reduce spacing to timpani staff
           #'( (basic-distance . 0) (minimum-distance . 0) (padding . 0.5 ) (stretchability . 0) ) }
      <<
        { \tenor }
        { \bass }
      >>
    >>
    \new Staff \with { \magnifyStaff #3/4 } { \clef bass \timpani }
  >>
  \layout { }
}
\score { \unfoldRepeats { << \trumpet \\ \soprano \\ \alto \\ \tenor \\ \bass \\ \timpani >> }
  \midi {
    \context { \Score midiChannelMapping = #'instrument }
    \context { \Staff \remove "Staff_performer" }
    \context { \Voice \consists "Staff_performer" }
  }
}
</score>

== Manuscripts and publication ==
The manuscripts of the original parts of {{lang|de|Lobe den Herren}} are extant, while the original score is lost. An extant copy of the score made by [[Christian Friedrich Penzel]], and dated 1755, assigns the cantata to [[John the Baptist|St. John's Day]] (24 June). It is unclear if this designation was copied from Bach's score.{{sfn|Wolf|2015}}

The first critical edition of the cantata, edited by [[Wilhelm Rust]], was published by the [[Bach Gesellschaft]] in 1881 as part of its complete edition of Bach's works. In the ''[[Neue Bach-Ausgabe]]'', the second edition of Bach's works, the cantata was published in 1986, edited by [[Klaus Hofmann]].{{sfn|''Bach Digital''|2025}}{{sfn|Wolf|2015}}

